/// The own order of a scene, if the table has it.
pub fn keys(extension: &str, scene: &str) -> Option<Vec<String>> {
    SCENES.iter().find(|(e, s, _)| *e == extension && *s == scene).map(|(_, _, keys)| keys.iter().map(|k| k.to_string()).collect())
}

/// The icon (empty: none) and the tooltip of a button of the table.
pub fn button(id: &str) -> Option<(&'static str, &'static str)> {
    BUTTONS.iter().find(|(i, _, _)| *i == id).map(|(_, icon, tip)| (*icon, *tip))
}
